  function normalizeAdminIcons(scope = document) { if (role !== 'admin') return; scope.querySelectorAll('[data-dash] .template-nav-icon').forEach((node) => { const id = node.closest('[data-dash]')?.dataset.dash; const icon = adminIconMap[id]; if (icon && node.dataset.iconReady !== '1') { node.innerHTML = `<i class="bi bi-${icon}" aria-hidden="true"></i>`; node.dataset.iconReady = '1'; } }); scope.querySelectorAll('.template-sidebar .template-logo').forEach((node) => { if (node.dataset.iconReady !== '1') { node.innerHTML = '<i class="bi bi-bus-front-fill" aria-hidden="true"></i>'; node.dataset.iconReady = '1'; } }); scope.querySelectorAll('#menu-toggle,#template-sidebar-toggle,#template-theme-toggle,#open-notifications').forEach((node) => { if (node.dataset.iconReady === '1') return; const icons = { 'menu-toggle':'list', 'template-sidebar-toggle':'layout-sidebar-inset', 'template-theme-toggle':'moon-stars', 'open-notifications':'bell' }; const icon = icons[node.id]; if (icon) { node.innerHTML = `<i class="bi bi-${icon}" aria-hidden="true"></i>`; node.dataset.iconReady = '1'; } }); }
