  function normalizeAdminActionIcons(scope = document) { if (role !== 'admin') return; const actions = { '[data-entity-edit]':'pencil-square', '[data-entity-delete]':'trash3', '[data-entity-status]':'power', '[data-entity-view]':'eye', '[data-company-gallery-view]':'images' }; Object.entries(actions).forEach(([selector, icon]) => scope.querySelectorAll(selector).forEach((node) => { if (node.dataset.iconReady === '1') return; node.insertAdjacentHTML('afterbegin', `<i class="bi bi-${icon}" aria-hidden="true"></i>`); node.dataset.iconReady = '1'; })); }
  if (role === 'admin' && root) { const actionIconObserver = new MutationObserver(() => normalizeAdminActionIcons(root)); actionIconObserver.observe(root, { childList: true, subtree: true }); }
  const apiBase = document.body.dataset.apiBase || 'api/v1';
  const appBasePath = new URL(apiBase, location.href).pathname.replace(/\/api\/v1\/?$/, '') || '';
  const fixedAdminPage = root?.dataset.adminPage || '';
  const fixedPublicPage = root?.dataset.publicPage || '';
  const state = { csrf: document.querySelector('meta[name="csrf-token"]')?.content || '', user: null, countries: [], cities: [], companies: [], routes: [], contactChannels: [], settings: null, search: null, trip: null, seats: [], selectedSeats: [], pendingPassengerValues: null, dashboardPage: role==='customer'?'home':(fixedAdminPage || sessionStorage.getItem('bus-dashboard-page')||'home') };
  const agentDashboardPages = new Set(['home','bookings','wallet','transactions','commissions','tickets']);
