  function openCompanyGalleryModal(company,images){const logo=mediaPath(company.logo_path);const cover=mediaPath(company.cover_image_path);const gallery=companyGallery(images,6);const media=[logo?{src:logo,label:'الشعار',kind:'logo'}:null,cover?{src:cover,label:'الصورة التعريفية',kind:'cover'}:null,...gallery.map((image)=>({src:mediaPath(image.image_path),label:`صورة المعرض ${image.image_order}`,kind:'gallery'}))].filter(Boolean);const cards=media.map((image,index)=>`<figure class="company-gallery-item company-gallery-item--${image.kind}"><img src="${image.src}" alt="${esc(image.label)} ${esc(company.trade_name)}" loading="eager"><figcaption><span>${esc(image.label)}</span><b>${index+1}</b></figcaption></figure>`).join('');modal(`<section class="company-gallery-dialog"><header><div><h3>معرض صور ${esc(company.trade_name)}</h3><p class="muted">الشعار والصورة التعريفية وصور المعرض في مكان واحد.</p></div><span class="company-gallery-count">${media.length} ${media.length===1?'صورة':'صور'}</span></header>${cards?`<div class="company-gallery-modal-grid">${cards}</div>`:empty('لا توجد صور مسجلة لهذه الشركة بعد.')}</section>`,'company-gallery-modal');}
  const closeModal = () => { $$('.modal-backdrop').forEach((layer) => layer.remove()); document.body.classList.remove('modal-open'); document.documentElement.classList.remove('modal-open'); document.body.style.removeProperty('overflow'); };
