    root.innerHTML = `${customerHeader()}<main class="booking-layout passenger-booking-layout"><section class="card booking-main passenger-main"><div class="passenger-step-head"><div><span class="seat-eyebrow"><i class="bi bi-person-vcard"></i> خطوة 2 من 2</span><h1>بياناتي الشخصية</h1><p class="muted">أدخل بيانات المسافر لكل مقعد اخترته، ثم أرسل طلب الحجز.</p></div><button class="btn btn-outline btn-sm" data-action="back-seats"><i class="bi bi-arrow-right"></i> العودة للمقاعد</button></div>${loginNote}<form id="booking-form">${state.selectedSeats.map((seat, index) => passengerInputs(seat,index)).join('')}<button class="btn btn-primary passenger-submit" type="submit"><i class="bi bi-send"></i> ${submitLabel}</button></form></section><aside class="card booking-sidebar passenger-summary-card"><div class="summary-card-heading"><div><span>ملخص الرحلة</span><h2>بيانات الحجز</h2></div><span class="summary-step">2/2</span></div><div class="summary-route-card"><div class="summary-route-line"><strong>${esc(originCity)}</strong><i class="bi bi-arrow-left"></i><strong>${esc(destinationCity)}</strong></div><span>${esc(dateTime(state.trip.departure_at))}</span></div><div class="summary-row"><span>شركة النقل</span><b>${esc(state.trip.company_name)}</b></div><div class="summary-row"><span>المقاعد</span><b>${esc(state.selectedSeats.join('، '))}</b></div><div class="summary-total">${money(Number(segment.amount)*state.selectedSeats.length,segment.currency_symbol)}</div></aside></main>`;
