  function passengerInputs(seat,index) { return `<section class="passenger-form"><h3>المسافر ${index+1} — المقعد ${esc(seat)}</h3><div class="form-grid"><div class="field wide"><label>الاسم الرباعي الكامل</label><input name="full_name_ar_${index}" required></div><div class="field"><label>رمز الدولة</label><input name="phone_country_code_${index}" value="+967" required></div><div class="field"><label>رقم الهاتف</label><input name="phone_${index}" required></div><div class="field"><label>رقم الجواز</label><input name="passport_number_${index}" required></div><div class="field"><label>تاريخ الميلاد</label><input name="birth_date_${index}" type="date" required></div><div class="field"><label>مكان الميلاد</label><input name="birth_place_${index}" required></div><div class="field"><label>تاريخ إصدار الجواز</label><input name="passport_issue_date_${index}" type="date" required></div><div class="field wide"><label>مكان إصدار الجواز</label><input name="passport_issue_place_${index}" required></div></div></section>`; }
  async function submitBooking(event) { event.preventDefault(); const form = new FormData(event.currentTarget); const values = Object.fromEntries(form.entries()); const passengers = state.selectedSeats.map((_, index) => ({ full_name_ar: values[`full_name_ar_${index}`], phone_country_code: values[`phone_country_code_${index}`], phone: values[`phone_${index}`], passport_number: values[`passport_number_${index}`], birth_date: values[`birth_date_${index}`], birth_place: values[`birth_place_${index}`], passport_issue_date: values[`passport_issue_date_${index}`], passport_issue_place: values[`passport_issue_place_${index}`] })); if (!state.user) { state.pendingPassengerValues = values; return openAuth('login', 'تم حفظ بياناتك. سجّل الدخول الآن لإرسال طلب الحجز.'); } try { const { booking } = await api('bookings', { method:'POST', body:JSON.stringify({ trip_id: state.trip.id, segment_id:state.trip.segmentId, seats:state.selectedSeats, passengers }) }); state.pendingPassengerValues = null; showToast('تم إرسال طلب الحجز بنجاح.', 'success'); renderBookingSuccess(booking); } catch (error) { showToast(error.message,'error'); } }
  function renderBookingSuccess(booking) {
    const segment = booking.segments?.[0] || {};
    const passengers = Array.isArray(booking.passengers) ? booking.passengers : [];
    const origin = segment.origin_name_ar || 'مدينة الانطلاق';
    const destination = segment.destination_name_ar || 'الوجهة';
    const seatCodes = passengers.map((passenger) => passenger.seat_code).filter(Boolean);
    const statusLabel = status(booking.status || 'pending');
    const passengerRows = passengers.length ? passengers.map((passenger, index) => `<div class="ticket-passenger-row"><span class="ticket-passenger-index">${index + 1}</span><div><strong>${esc(passenger.full_name_ar || 'مسافر')}</strong><small>بيانات المسافر محفوظة في الحجز</small></div><b><i class="bi bi-grid-3x3-gap"></i> ${esc(passenger.seat_code || '—')}</b></div>`).join('') : '<p class="muted">لا توجد بيانات مسافرين معروضة.</p>';
    root.innerHTML = `${customerHeader()}<main class="results-wrap ticket-page"><div class="ticket-page-heading"><span class="seat-eyebrow"><i class="bi bi-check2-circle"></i> اكتملت الخطوة الأخيرة</span><h1>تم إرسال طلب الحجز</h1><p>احتفظ ببيانات التذكرة. سيظهر التأكيد النهائي بعد مراجعة الإدارة.</p></div><section class="ticket-card modern-ticket" aria-label="تذكرة الحجز"><header class="modern-ticket-head"><div class="ticket-brand-lockup"><span class="ticket-brand-mark"><i class="bi bi-bus-front-fill"></i></span><div><span>منصة رحلة</span><strong>${esc(booking.company_name || 'شركة النقل')}</strong></div></div><div class="ticket-status-block"><span>حالة الطلب</span>${statusLabel}</div><div class="ticket-reference"><span>رقم الحجز</span><strong>${esc(booking.booking_number || '—')}</strong></div></header><div class="ticket-perforation" aria-hidden="true"><i></i><span></span><i></i></div><div class="modern-ticket-body"><div class="ticket-route-hero"><div class="ticket-city"><span>من</span><strong>${esc(origin)}</strong></div><div class="ticket-route-arrow"><i class="bi bi-arrow-left"></i><small>مسار الرحلة</small></div><div class="ticket-city destination"><span>إلى</span><strong>${esc(destination)}</strong></div></div><div class="ticket-time-strip"><div><span><i class="bi bi-calendar3"></i> موعد الرحلة</span><strong>${esc(dateTime(booking.departure_at))}</strong></div><div><span><i class="bi bi-clock"></i> مهلة التأكيد</span><strong>${esc(dateTime(booking.held_until))}</strong></div></div><div class="ticket-facts"><div><span>رقم الرحلة</span><strong>${esc(booking.trip_number || '—')}</strong></div><div><span>المقاعد</span><strong>${esc(seatCodes.join('، ') || '—')}</strong></div><div><span>الإجمالي</span><strong>${money(booking.total_amount, booking.currency_symbol)}</strong></div></div><section class="ticket-passengers"><div class="ticket-section-title"><div><span>بيانات المسافرين</span><h2>المقاعد المحجوزة</h2></div><span class="ticket-count">${passengers.length} ${passengers.length === 1 ? 'مسافر' : 'مسافرين'}</span></div>${passengerRows}</section><div class="ticket-qr-area"><div><span class="ticket-qr-kicker"><i class="bi bi-qr-code"></i> رمز الحجز</span><h3>احتفظ بهذه التذكرة</h3><p>يمكن استخدام رقم الحجز عند التواصل مع الدعم أو متابعة حالة الطلب من حسابك.</p></div><div class="ticket-qr-box"><div id="booking-qr" role="img" aria-label="رمز QR للحجز"></div><small>${esc(booking.booking_number || '')}</small></div></div><div class="ticket-notice"><i class="bi bi-info-circle"></i><span>هذه تذكرة طلب حجز، وسيتم إصدار التذكرة النهائية بعد تأكيد الإدارة.</span></div></div><footer class="ticket-actions"><button class="btn btn-primary" data-action="customer-bookings"><i class="bi bi-ticket-perforated"></i> عرض حجوزاتي</button><button class="btn btn-outline" data-action="home"><i class="bi bi-house"></i> العودة للرئيسية</button></footer></section></main>`;
    window.RihlaPublicTemplate?.bindChrome?.(publicTemplateContext());
    const qrTarget = $('#booking-qr');
    if (qrTarget && window.QRCode) {
      if (typeof window.QRCode.toCanvas === 'function') window.QRCode.toCanvas(qrTarget, String(booking.booking_number || ''), { width: 132, margin: 1, color: { dark: '#12233e', light: '#ffffff' } }, () => {});
      else new window.QRCode(qrTarget, { text: String(booking.booking_number || ''), width: 132, height: 132, colorDark: '#12233e', colorLight: '#ffffff', correctLevel: window.QRCode.CorrectLevel?.M || 0 });
    }
    $('[data-action="customer-bookings"]')?.addEventListener('click', showCustomerBookings);
    $('[data-action="home"]')?.addEventListener('click', renderCustomerHome);
  }
  async function showCustomerBookings() { if (!state.user) return openAuth('login'); try { const { items } = await api('bookings'); root.innerHTML = `${customerHeader()}<main class="results-wrap"><div class="page-heading"><div><h1>حجوزاتي</h1><p class="muted">تابع الحالة والتذاكر من حسابك.</p></div><button class="btn btn-outline btn-sm" data-action="home">العودة للرئيسية</button></div><div class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>رقم الحجز</th><th>الرحلة</th><th>التاريخ</th><th>الإجمالي</th><th>الحالة</th><th></th></tr></thead><tbody>${items.length?items.map((item)=>`<tr><td>${esc(item.booking_number)}</td><td>${esc(item.trip_number)}</td><td>${dateTime(item.departure_at)}</td><td>${money(item.total_amount,item.currency_symbol)}</td><td>${status(item.status)}</td><td><button class="btn btn-outline btn-sm" data-booking-detail="${item.id}">عرض</button></td></tr>`).join(''):`<tr><td colspan="6">${empty('لا توجد حجوزات بعد.')}</td></tr>`}</tbody></table></div></div></main>`; window.RihlaPublicTemplate?.bindChrome?.(publicTemplateContext()); $('[data-action="home"]')?.addEventListener('click', renderCustomerHome); $$('[data-booking-detail]').forEach((button)=>button.addEventListener('click',()=>showBookingDetail(Number(button.dataset.bookingDetail)))); } catch(error){showToast(error.message,'error');} }
  async function showBookingDetail(id) { try { const { booking } = await api(`bookings/${id}`); const canReview = ['confirmed','completed'].includes(String(booking.status)) && booking.departure_at && new Date(String(booking.departure_at).replace(' ','T')) < new Date(); const layer = modal(`<button class="close">×</button><h2>الحجز ${esc(booking.booking_number)}</h2><p>${status(booking.status)}</p><div class="panel" style="margin-top:14px"><div class="panel-body">${booking.passengers.map(p=>`<div class="summary-row"><span>${esc(p.full_name_ar)}</span><b>المقعد ${esc(p.seat_code)}</b></div>`).join('')}<div class="summary-total">${money(booking.total_amount,booking.currency_symbol)}</div></div></div>${booking.status==='pending'?`<div class="modal-actions"><button class="btn btn-danger-outline" data-cancel-booking="${booking.id}">إلغاء الحجز</button></div>`:''}${canReview?`<form class="review-form" data-review-form="${booking.id}"><h3>قيّم رحلتك</h3><div class="field"><label>التقييم</label><select name="rating" required><option value="">اختر من 1 إلى 5 نجوم</option><option value="5">★★★★★ ممتاز</option><option value="4">★★★★ جيد جدًا</option><option value="3">★★★ جيد</option><option value="2">★★ يحتاج تحسين</option><option value="1">★ ضعيف</option></select></div><label class="checkbox-line"><input type="checkbox" name="recommendation" value="1" checked> أوصي بهذه الرحلة</label><div class="field"><label>ملاحظتك</label><textarea name="comment" maxlength="1000" rows="3" placeholder="اكتب ملاحظتك الاختيارية"></textarea></div><button class="btn btn-primary" type="submit">إرسال التقييم</button></form>`:''}`); $('[data-cancel-booking]')?.addEventListener('click',()=>cancelBooking(id)); $('[data-review-form]',layer)?.addEventListener('submit',async event=>{event.preventDefault();try{const values=Object.fromEntries(new FormData(event.currentTarget));values.recommendation=event.currentTarget.querySelector('[name="recommendation"]').checked;await api(`bookings/${id}/review`,{method:'POST',body:JSON.stringify(values)});showToast('تم حفظ تقييمك.','success');event.currentTarget.innerHTML='<p class="status active">تم إرسال تقييمك بنجاح.</p>';}catch(error){showToast(error.message,'error');}}); } catch(error){showToast(error.message,'error');} }
  async function cancelBooking(id){ try{await api(`bookings/${id}/cancel`,{method:'POST',body:JSON.stringify({reason:'تم الإلغاء من حساب العميل.'})});closeModal();showToast('تم إلغاء الحجز.','success');showCustomerBookings();}catch(error){showToast(error.message,'error');} }

  function ensureMinimalAuthStyle() {
    if ($('#auth-minimal-style')) return;
    const style = document.createElement('style');
    style.id = 'auth-minimal-style';
    style.textContent = `.auth-backdrop{position:fixed!important;inset:0!important;z-index:120!important;display:grid!important;place-items:center!important;padding:18px!important;background:rgb(15 23 42/.68)!important;backdrop-filter:blur(5px)!important}.auth-backdrop .auth-modal{position:relative!important;width:min(470px,100%)!important;max-height:calc(100vh - 36px)!important;overflow:auto!important;border:0!important;border-radius:22px!important;background:#fff!important;box-shadow:0 28px 75px rgb(2 12 27/.4)!important}.auth-backdrop .auth-modal:before{content:'';position:absolute;right:30px;left:30px;top:0;height:4px;border-radius:0 0 99px 99px;background:linear-gradient(90deg,#f0b429,#fde68a,#1e3a8a)}.auth-backdrop .auth-shell{display:block!important;min-height:0!important}.auth-backdrop .auth-visual{display:none!important}.auth-backdrop .auth-content{position:relative!important;padding:44px 38px 34px!important;background:#fff!important;border-radius:22px!important}.auth-backdrop .auth-content:before{content:'🚌';width:54px;height:54px;display:grid;place-items:center;margin:0 0 19px;border-radius:17px;background:linear-gradient(145deg,#1e3a8a,#0f2767);box-shadow:0 12px 24px rgb(30 58 138/.2);font-size:1.45rem}.auth-backdrop .auth-content:after{content:'منصة الحجوزات';position:absolute;top:52px;right:106px;color:#1e3a8a;font-size:.82rem;font-weight:900}.auth-backdrop .close{position:absolute;z-index:2;left:18px;top:18px;width:34px;height:34px;border:1px solid #e6edf6;border-radius:11px;background:#f8fafc;color:#64748b;font-size:1.4rem;line-height:1;cursor:pointer}.auth-backdrop .auth-eyebrow{display:block;margin-top:3px;color:#c48008;font-size:.73rem;font-weight:900}.auth-backdrop .auth-content h2{margin:9px 0 7px;color:#0f172a;font-size:1.62rem;font-weight:900}.auth-backdrop .auth-description{margin:0;padding-bottom:20px;border-bottom:1px solid #edf1f7;color:#64748b;font-size:.89rem;line-height:1.75}.auth-backdrop .auth-form{display:grid;gap:14px;margin-top:21px}.auth-backdrop .field label{display:block;margin:0 0 7px;color:#475569;font-size:.82rem;font-weight:800}.auth-backdrop .field input,.auth-backdrop .field select{width:100%;min-height:49px;border:1px solid #dce5f1;border-radius:11px;background:#fbfcfe;padding:10px 14px;color:#0f172a;font:inherit;outline:none}.auth-backdrop .field input:focus,.auth-backdrop .field select:focus{background:#fff;border-color:#1e3a8a;box-shadow:0 0 0 4px rgb(30 58 138/.09)}.auth-backdrop .auth-input-wrap{position:relative}.auth-backdrop .auth-input-wrap input{padding-right:42px!important}.auth-backdrop .auth-input-wrap #auth-password{padding-left:61px!important}.auth-backdrop .auth-input-icon{position:absolute;right:14px;top:50%;transform:translateY(-50%);color:#1e3a8a;pointer-events:none}.auth-backdrop .auth-password-toggle{position:absolute;left:9px;top:50%;transform:translateY(-50%);border:0;border-radius:8px;background:transparent;color:#1e3a8a;padding:5px 8px;font:inherit;font-size:.73rem;font-weight:900;cursor:pointer}.auth-backdrop .auth-field-note{margin:7px 0 0;color:#94a3b8;font-size:.72rem;font-weight:700}.auth-backdrop .auth-registration-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.auth-backdrop .auth-submit{display:block;margin-top:5px}.auth-backdrop .auth-submit .btn{width:100%;min-height:51px;border:0;border-radius:11px;background:linear-gradient(135deg,#18377f,#2859bd);box-shadow:0 10px 19px rgb(30 58 138/.2);color:#fff;font:inherit;font-weight:900;cursor:pointer}.auth-backdrop .modal-switch{margin:18px 0 0;text-align:center;color:#64748b;font-size:.84rem}.auth-backdrop .linkish{border:0;background:transparent;color:#1d4ed8;font:inherit;font-weight:900;cursor:pointer;text-decoration:underline;text-underline-offset:3px}@media (max-width:520px){.auth-backdrop{padding:12px!important}.auth-backdrop .auth-modal{border-radius:19px!important}.auth-backdrop .auth-content{padding:38px 23px 27px!important;border-radius:19px!important}.auth-backdrop .auth-content:before{width:48px;height:48px;margin-bottom:17px;border-radius:15px;font-size:1.25rem}.auth-backdrop .auth-content:after{top:47px;right:86px;font-size:.75rem}.auth-backdrop .auth-content h2{font-size:1.42rem}.auth-backdrop .auth-description{padding-bottom:17px}.auth-backdrop .auth-registration-grid{grid-template-columns:1fr}.auth-backdrop .close{left:14px;top:14px}}`;
    document.head.append(style);
  }
  async function openAuth(mode = 'login', hint = '') {
    ensureMinimalAuthStyle();
    if (!document.getElementById('auth-brand-style')) { const style = document.createElement('style'); style.id = 'auth-brand-style'; style.textContent = `.auth-backdrop .auth-content:before{content:var(--auth-brand-mark,'🚌')!important;background-image:var(--auth-brand-image,none);background-position:center;background-repeat:no-repeat;background-size:contain}.auth-backdrop .auth-content:after{content:var(--auth-brand-name,'منصة الحجوزات')!important}`; document.head.append(style); }
    try { await preloadPublic(); } catch {}
    const authSettings = state.settings || { site_name_ar: 'منصة رحلة', logo_path: '' };
    const authBrandName = String(authSettings.site_name_ar || 'منصة رحلة');
    const authLogo = mediaPath(authSettings.logo_path);
    const isLogin = mode === 'login';
    const fields = mode === 'register' ? `<div class="auth-registration-grid"><div class="field"><label>الاسم الكامل</label><input name="full_name" autocomplete="name" placeholder="اكتب اسمك الكامل" required></div><div class="field"><label>رقم الهاتف</label><input name="phone" inputmode="tel" autocomplete="tel" placeholder="مثال: 777 000 000" required></div><div class="field"><label>الدولة</label><select id="auth-country" name="country_id">${state.countries.map(c=>`<option value="${c.id}">${esc(c.name_ar)}</option>`).join('')}</select></div><div class="field"><label>المدينة</label><select id="auth-city" name="city_id">${cityOptions()}</select></div></div>` : '';
    const title = isLogin ? 'سعداء بعودتك' : 'أنشئ حسابك في دقائق';
    const description = hint || (isLogin ? 'سجّل الدخول لمتابعة حجوزاتك وتذاكرك من مكان واحد.' : 'ابدأ تجربة حجز أبسط واحفظ تفاصيل رحلاتك بأمان.');
    const identifierField = isLogin ? '<div class="field"><label>البريد الإلكتروني أو اسم المستخدم</label><div class="auth-input-wrap"><span class="auth-input-icon" aria-hidden="true">✉</span><input name="email" autocomplete="username" placeholder="مثال: محمد أو name@example.com" required></div></div>' : '<div class="field"><label>البريد الإلكتروني</label><div class="auth-input-wrap"><span class="auth-input-icon" aria-hidden="true">✉</span><input name="email" type="email" autocomplete="email" placeholder="name@example.com" required></div></div>';
    const backdrop = modal(`<div class="auth-shell" data-auth-mode="${mode}"><aside class="auth-visual" aria-hidden="true"><div class="auth-visual-glow"></div><span class="auth-visual-mark">🚌</span><span class="auth-visual-kicker">رحلتك تبدأ من هنا</span><h2>حجوزاتك بوضوح، من أول بحث إلى آخر تذكرة.</h2><p>ابحث، احجز، وتابع رحلاتك من حساب واحد مصمم ليوفّر عليك الوقت.</p><div class="auth-benefits"><span>✓ حجز آمن</span><span>✓ تأكيد واضح</span><span>✓ تذاكرك دائمًا قريبة</span></div></aside><div class="auth-content"><span class="auth-eyebrow">${isLogin ? 'تسجيل الدخول' : 'حساب عميل جديد'}</span><h2>${title}</h2><p class="auth-description">${esc(description)}</p><form id="auth-form" class="auth-form">${fields}${identifierField}<div class="field"><label>كلمة المرور</label><div class="auth-input-wrap"><span class="auth-input-icon" aria-hidden="true">●</span><input id="auth-password" name="password" type="password" autocomplete="${isLogin ? 'current-password' : 'new-password'}" minlength="10" placeholder="ثمانية أحرف أو أكثر" required><button class="auth-password-toggle" type="button" data-action="toggle-password" aria-label="إظهار كلمة المرور" aria-pressed="false">إظهار</button></div>${isLogin ? '<p class="auth-field-note">تُحفظ بياناتك ضمن جلسة آمنة.</p>' : '<p class="auth-field-note">اختر كلمة مرور قوية لحماية حسابك.</p>'}</div><div class="modal-actions auth-submit"><button type="submit" class="btn btn-primary">${isLogin ? 'دخول إلى حسابي' : 'إنشاء الحساب والمتابعة'} <span aria-hidden="true">←</span></button></div></form><p class="modal-switch">${isLogin ? 'ليس لديك حساب؟' : 'لديك حساب بالفعل؟'} <button class="linkish" id="auth-switch">${isLogin ? 'أنشئ حسابًا الآن' : 'سجّل الدخول'}</button></p></div></div>`, 'auth-modal');
    backdrop.classList.add('auth-backdrop'); backdrop.style.setProperty('--auth-brand-name', JSON.stringify(authBrandName)); backdrop.style.setProperty('--auth-brand-image', authLogo ? `url("${authLogo}")` : 'none'); backdrop.style.setProperty('--auth-brand-mark', authLogo ? "''" : "'🚌'");
    $('#auth-switch',backdrop).addEventListener('click',()=>openAuth(mode==='login'?'register':'login'));
    $('[data-action="toggle-password"]',backdrop)?.addEventListener('click', (event) => { const password = $('#auth-password', backdrop); const visible = password.type === 'text'; password.type = visible ? 'password' : 'text'; event.currentTarget.textContent = visible ? 'إظهار' : 'إخفاء'; event.currentTarget.setAttribute('aria-label', visible ? 'إظهار كلمة المرور' : 'إخفاء كلمة المرور'); event.currentTarget.setAttribute('aria-pressed', String(!visible)); });
    $('#auth-country',backdrop)?.addEventListener('change', async(event)=>{ const data=await api(`cities?country_id=${event.target.value}`); state.cities=data.items; $('#auth-city',backdrop).innerHTML=cityOptions(); });
    $('#auth-form',backdrop).addEventListener('submit', async(event)=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));try{const response=await api(mode==='login'?'auth/login':'auth/register',{method:'POST',body:JSON.stringify(data)});state.user=response.user;closeModal();showToast(mode==='login'?'مرحبًا بعودتك.':'تم إنشاء الحساب بنجاح.','success');if(role==='customer'){ state.trip?renderPassengerForm():renderCustomerHome(); }else renderDashboard();}catch(error){showToast(error.message,'error');}});
  }
  async function logout(){try{await api('auth/logout',{method:'POST',body:'{}'});}catch{}state.user=null;state.csrf='';if(role==='customer')renderCustomerHome();else renderLoginGate();}

  function renderLoginGate() { root.innerHTML=`<section class="card login-gate"><div class="brand"><span class="brand-mark">🚌</span><span>منصة الحجوزات</span></div><h1 style="margin:24px 0 9px">تسجيل الدخول إلى اللوحة</h1><p class="muted">هذه الصفحة مخصصة للمستخدمين المخولين فقط.</p><button class="btn btn-primary" id="gate-login" style="margin-top:16px">تسجيل الدخول</button></section>`; $('#gate-login').addEventListener('click',()=>openAuth('login')); }
