      const renderProfit=()=>{if(!sale||!cost||!output)return;const margin=(Number(sale.value)||0)-(Number(cost.value)||0);output.textContent=`هامش الربح: ${margin.toLocaleString('ar-YE',{minimumFractionDigits:2,maximumFractionDigits:2})}`;output.classList.toggle('is-loss',margin<0);output.title=margin<0?'تحذير: سعر البيع أقل من سعر الشركة وقد ينتج عنه خسارة.':'';};
