  function renderDashboard(active='home') { if(!state.user) return renderLoginGate(); const agent = role==='agent'; const permitted = agent?state.user.roles.includes('agent'):state.user.roles.some(r=>['super_admin','company_admin','booking_officer','accountant','support'].includes(r)); if(!permitted) return renderLoginGate(); ensureDashboardTemplateStyle(); const meta=dashboardPageMeta[active]||dashboardPageMeta.home; const initial=esc((state.user.full_name||'م').trim().slice(0,1)); const roleLabel=agent?'وكيل':state.user.roles.includes('super_admin')?'مدير رئيسي':state.user.roles.includes('company_admin')?'مدير شركة':state.user.roles.includes('booking_officer')?'موظف حجوزات':state.user.roles.includes('accountant')?'محاسب':'موظف دعم'; root.innerHTML=`<div class="dashboard-shell template-dashboard" id="template-dashboard"><div class="template-overlay" id="template-overlay"></div>${dashboardSidebar(active)}<section class="template-main"><header class="template-topbar"><div class="template-topbar-group"><button class="template-icon-btn template-menu-toggle" id="menu-toggle" aria-label="فتح القائمة">☰</button><button class="template-icon-btn template-sidebar-toggle" id="template-sidebar-toggle" aria-label="طي القائمة">▤</button><div><h1 id="template-page-title">${meta[0]}</h1><p class="template-breadcrumb" id="template-page-breadcrumb">${meta[1]}</p></div></div><div class="template-topbar-group"><label class="template-search"><span>⌕</span><input id="dashboard-quick-search" placeholder="انتقال سريع إلى قسم…" autocomplete="off"></label><button class="template-icon-btn" id="template-theme-toggle" aria-label="تبديل الوضع">◐</button><button class="template-icon-btn template-notification" id="open-notifications" aria-label="الإشعارات"><span aria-hidden="true">♢</span><b class="notification-badge" id="notification-badge" hidden>0</b></button><button class="template-user" id="template-user-menu" type="button"><span class="template-user-avatar">${initial}</span><span class="template-user-info">${esc(state.user.full_name)}<small>${roleLabel}</small></span></button></div></header><main class="dash-page" id="dash-page"></main></section></div>`; const shell=$('#template-dashboard'); const sidebar=$('#sidebar'); const overlay=$('#template-overlay'); const setMobileMenu=(open)=>{const isOpen=Boolean(open);sidebar?.classList.toggle('open',isOpen);overlay?.classList.toggle('open',isOpen);document.body.classList.toggle('admin-mobile-menu-open',isOpen);document.documentElement.classList.toggle('admin-mobile-menu-open',isOpen);$('#menu-toggle')?.setAttribute('aria-expanded',String(isOpen));}; const closeMobile=()=>setMobileMenu(false); $('#menu-toggle')?.setAttribute('aria-expanded','false'); $('#menu-toggle')?.addEventListener('click',()=>setMobileMenu(!sidebar?.classList.contains('open'))); $('#template-sidebar-toggle')?.addEventListener('click',()=>sidebar?.classList.toggle('is-collapsed')); overlay?.addEventListener('click',closeMobile); if(!document.body.dataset.adminMobileMenuBound){document.body.dataset.adminMobileMenuBound='1';document.addEventListener('keydown',(event)=>{if(event.key!=='Escape')return;const current=document.querySelector('#sidebar');if(current?.classList.contains('open')){current.classList.remove('open');document.querySelector('#template-overlay')?.classList.remove('open');document.body.classList.remove('admin-mobile-menu-open');document.documentElement.classList.remove('admin-mobile-menu-open');document.querySelector('#menu-toggle')?.setAttribute('aria-expanded','false');}});} $('#template-theme-toggle')?.addEventListener('click',()=>{const dark=shell.dataset.theme==='dark';shell.dataset.theme=dark?'light':'dark';localStorage.setItem('bus-admin-theme',dark?'light':'dark');}); if(localStorage.getItem('bus-admin-theme')==='dark')shell.dataset.theme='dark'; $('#dashboard-quick-search')?.addEventListener('keydown',(event)=>{if(event.key!=='Enter')return;const query=event.currentTarget.value.trim();const found=Object.entries(dashboardPageMeta).find(([,value])=>value[0].includes(query));if(found){event.currentTarget.value='';loadDashboardPage(found[0]);}else if(query)showToast('اكتب اسم قسم مثل: الحجوزات أو التقارير.','info');}); $$('[data-dash]').forEach(button=>button.addEventListener('click',()=>{closeMobile();loadDashboardPage(button.dataset.dash);})); $('[data-action="logout"]')?.addEventListener('click',logout);     $('#open-notifications')?.addEventListener('click',showNotifications); $('#template-user-menu')?.addEventListener('click',showProfileMenu); loadDashboardPage(active); refreshNotificationBadge(); }

