  showNotifications = async function(asPage = false) { try { const {items, unread_count} = await api('notifications'); const list = items.length ? items.map(item => `<button type="button" class="notification-row ${item.read_at ? '' : 'unread'}" data-notification-id="${esc(item.id)}"><span class="notification-row-icon">${item.type === 'new_booking' ? '▣' : '♢'}</span><span><b>${esc(item.title_ar)}</b><small>${esc(item.body_ar)}</small><em>${dateTime(item.created_at)}</em></span><i>${item.read_at ? '✓' : 'جديد'}</i></button>`).join('') : empty('لا توجد إشعارات حاليًا.'); const content = `<div class="notifications-heading"><span class="status active">${Number(unread_count || 0)} غير مقروء</span><span class="muted">تصل إشعارات الحجوزات الجديدة تلقائيًا للمخولين.</span></div><div class="notifications-list">${list}</div>`; if (asPage) { $('#dash-page').innerHTML = `${dashTitle('الإشعارات','حجوزات جديدة وتنبيهات حسابك في مكان واحد.')}<section class="panel notification-panel"><div class="panel-body">${content}</div></section>`; } else { const layer = modal(`<h2>الإشعارات</h2>${content}`, 'notifications-dialog'); bindNotificationRows(layer); } if (asPage) bindNotificationRows($('#dash-page')); refreshNotificationBadge(); } catch (error) { showToast(error.message, 'error'); } };
  function bindNotificationRows(parent) { $$('[data-notification-id]', parent || document).forEach(button => button.addEventListener('click', async () => { try { await api(`notifications/${button.dataset.notificationId}/read`, {method:'PUT', body:'{}'}); button.classList.remove('unread'); button.querySelector('i').textContent = '✓'; refreshNotificationBadge(); } catch (error) { showToast(error.message, 'error'); } })); }
  function profileForm(user) { return `<form id="profile-form" class="form-grid"><div class="field"><label>الاسم الكامل</label><input name="full_name" value="${esc(user.full_name || '')}" minlength="3" required></div><div class="field"><label>البريد الإلكتروني</label><input name="email" type="email" value="${esc(user.email || '')}" required></div><div class="field"><label>رقم الهاتف</label><input name="phone" value="${esc(user.phone || '')}" minlength="5" required></div><div class="field wide"><label>كلمة مرور جديدة (اختيارية)</label><input name="password" type="password" minlength="10" autocomplete="new-password"><small class="muted">اتركها فارغة إذا لم ترغب في تغييرها.</small></div><div class="field wide"><button class="btn btn-primary" type="submit">حفظ بيانات الحساب</button></div></form>`; }
  function openProfileEditor() { if (!state.user) return openAuth('login'); const layer = modal(`<h3>تعديل بيانات الحساب</h3><p class="muted">حدّث بياناتك الأساسية أو غيّر كلمة المرور عند الحاجة.</p>${profileForm(state.user)}`, 'profile-editor-dialog'); $('#profile-form', layer)?.addEventListener('submit', async event => { event.preventDefault(); try { const values = Object.fromEntries(new FormData(event.currentTarget)); state.user = (await api('auth/me', {method:'PUT', body:JSON.stringify(values)})).user; closeModal(); showToast('تم تحديث بيانات الحساب.', 'success'); if (role === 'customer') renderCustomerHome(); else renderDashboard(fixedAdminPage || state.dashboardPage); } catch (error) { showToast(error.message, 'error'); } }); }
  function showProfileMenu() { if (!state.user) return openAuth('login'); const layer = modal(`<div class="profile-menu-card"><div class="profile-menu-avatar">${esc((state.user.full_name || 'م').trim().slice(0,1))}</div><h3>${esc(state.user.full_name)}</h3><p class="muted">${esc(state.user.email)}${state.user.phone ? ` · ${esc(state.user.phone)}` : ''}</p><div class="profile-menu-actions"><button class="btn btn-primary" type="button" data-profile-edit>تعديل بيانات المستخدم</button><button class="btn btn-outline" type="button" data-profile-logout>تسجيل الخروج</button></div></div>`, 'profile-menu-dialog'); $('[data-profile-edit]', layer)?.addEventListener('click', openProfileEditor); $('[data-profile-logout]', layer)?.addEventListener('click', async () => { closeModal(); await logout(); }); }
  function addSiteSettingsPanel(host, settings) { const panel = document.createElement('section'); panel.className = 'panel site-settings-panel'; panel.innerHTML = `<div class="panel-head"><div><h3>هوية الموقع ومحتواه</h3><span class="muted">تحكم باسم الموقع والشعار والأيقونة وحقوق النشر من مكان واحد.</span></div><span class="status active">إعدادات عامة</span></div><div class="panel-body"><form id="site-settings-form" class="form-grid"><div class="field"><label>اسم الموقع</label><input name="site_name_ar" maxlength="180" value="${esc(settings.site_name_ar || '')}" required></div><div class="field"><label>الوصف المختصر</label><input name="tagline_ar" maxlength="255" value="${esc(settings.tagline_ar || '')}" placeholder="احجز رحلتك بسهولة وأمان"></div><div class="field wide"><label>حقوق النشر والتذييل</label><input name="footer_text_ar" maxlength="255" value="${esc(settings.footer_text_ar || '')}" required></div><div class="field wide"><button class="btn btn-primary" type="submit">حفظ بيانات الهوية</button></div></form><div class="site-brand-upload-grid"><div class="site-brand-preview">${settings.logo_path ? `<img src="${mediaPath(settings.logo_path)}" alt="الشعار الحالي">` : '<span>الشعار</span>'}<b>شعار الموقع</b><label class="file-picker"><span>رفع/استبدال الشعار</span><input type="file" accept="image/jpeg,image/png,image/webp" data-site-media="logo"></label></div><div class="site-brand-preview">${settings.icon_path ? `<img src="${mediaPath(settings.icon_path)}" alt="الأيقونة الحالية">` : '<span>الأيقونة</span>'}<b>أيقونة الموقع</b><label class="file-picker"><span>رفع/استبدال الأيقونة</span><input type="file" accept="image/jpeg,image/png,image/webp" data-site-media="icon"></label></div></div></div>`; host.prepend(panel); $('#site-settings-form', panel)?.addEventListener('submit', async event => { event.preventDefault(); try { state.settings = (await api('admin/site-settings', {method:'PUT', body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))})).settings; showToast('تم حفظ إعدادات الموقع.', 'success'); } catch (error) { showToast(error.message, 'error'); } }); $$('[data-site-media]', panel).forEach(input => input.addEventListener('change', async event => { const file = event.currentTarget.files?.[0]; if (!file) return; try { const data = await uploadMedia('admin/site-settings/media', event.currentTarget.dataset.siteMedia, file); state.settings = data.settings; showToast('تم تحديث هوية الموقع.', 'success'); dashboardSettings(host); } catch (error) { showToast(error.message, 'error'); } })); }
  const baseDashboardSettingsEnhanced = dashboardSettings;
  dashboardSettings = async function(host) { const query=new URLSearchParams(location.search); const section=query.get('section')||'site'; const navigation=`<section class="panel settings-navigation"><div class="panel-head"><div><h3>أقسام إعدادات المنصة</h3><span class="muted">اختر القسم المطلوب بدل جمع النماذج في شاشة واحدة.</span></div></div><div class="panel-body settings-section-grid"><a class="settings-section-card ${section==='site'?'active':''}" href="settings.php?section=site"><b>هوية الموقع</b><small>الاسم والوصف والحقوق والشعار والأيقونة</small></a><a class="settings-section-card ${section==='contact'?'active':''}" href="settings.php?section=contact"><b>قنوات الاتصال</b><small>الهاتف والبريد وواتساب والعنوان وساعات العمل</small></a><a class="settings-section-card" href="contact_messages.php"><b>رسائل اتصل بنا</b><small>عرض الرسائل الواردة وإدارة حالتها</small></a><a class="settings-section-card" href="settings.php?section=bookings"><b>إعدادات الحجوزات</b><small>إدارة الحجوزات من صفحة الحجوزات الحالية</small></a><a class="settings-section-card" href="settings.php?section=agents"><b>إعدادات الوكلاء</b><small>بيانات الوكلاء من الصفحة المتخصصة</small></a><a class="settings-section-card" href="settings.php?section=customers"><b>إعدادات العملاء</b><small>بيانات العملاء من الصفحة المتخصصة</small></a><a class="settings-section-card" href="settings.php?section=ticket"><b>تصميم التذاكر</b><small>عرض وإدارة التذاكر من الصفحة الحالية</small></a><a class="settings-section-card" href="settings.php?section=about"><b>من نحن</b><small>معاينة الصفحة العامة؛ لا يوجد جدول مستقل لها في المخطط الحالي</small></a></div></section>`; host.innerHTML=`${dashTitle('الإعدادات','تنظيم إعدادات المنصة في أقسام مستقلة وواضحة.')}${navigation}`; const standaloneSections={bookings:{title:'إعدادات الحجوزات',text:'لا توجد حقول إعدادات حجز مستقلة محفوظة في المخطط الحالي؛ تم الحفاظ على الوظائف الحالية ونقل إدارتها إلى الصفحة المتخصصة.',link:'bookings.php',label:'فتح إدارة الحجوزات'},agents:{title:'إعدادات الوكلاء',text:'بيانات الوكلاء والعمولات والمحافظ محفوظة في الجداول التشغيلية الحالية وتدار من الصفحات المتخصصة.',link:'agent-finance.php',label:'فتح الإعدادات المالية للوكلاء'},customers:{title:'إعدادات العملاء',text:'إعدادات العملاء الحالية مرتبطة ببيانات الحسابات والعملاء، وتبقى إدارتها من الصفحة المتخصصة دون إنشاء حقول وهمية.',link:'customers.php',label:'فتح إدارة العملاء'},ticket:{title:'إعدادات تصميم التذكرة',text:'لا توجد إعدادات تصميم مستقلة محفوظة في قاعدة البيانات الحالية؛ تم الإبقاء على عرض التذاكر ووظائفها دون تغيير.',link:'tickets.php',label:'فتح إدارة التذاكر'},about:{title:'من نحن',text:'المحتوى الحالي لصفحة من نحن لا يملك حقولًا إدارية مستقلة في المخطط الحالي؛ هذه معاينة مباشرة للمحتوى العام دون تغييره.',link:'../about.php',label:'معاينة صفحة من نحن'}}; if(standaloneSections[section]){const item=standaloneSections[section];host.insertAdjacentHTML('beforeend',`<section class="panel settings-standalone-panel"><div class="panel-head"><h3>${item.title}</h3></div><div class="panel-body"><p class="muted">${item.text}</p><a class="btn btn-outline" href="${item.link}">${item.label}</a></div></section>`);return;} if(section==='contact'){ try { await baseDashboardSettingsEnhanced(host); host.querySelector('.dash-title')?.insertAdjacentHTML('afterend',navigation); } catch(error){ host.innerHTML=`${dashTitle('الإعدادات','تنظيم إعدادات المنصة في أقسام مستقلة وواضحة.')}${navigation}<section class="panel"><div class="panel-body">${empty(error.message)}</div></section>`; } return; } try { const {settings}=await api('admin/site-settings'); state.settings=settings; addSiteSettingsPanel(host,settings); } catch(error){ host.insertAdjacentHTML('beforeend',`<section class="panel"><div class="panel-body">${empty(error.message)}</div></section>`); } };
  const baseDashboardHomeEnhanced = dashboardHome;
  dashboardHome = async function(host) { await baseDashboardHomeEnhanced(host); try { const {summary} = await api('dashboard/summary'); const extra = document.createElement('section'); extra.className = 'dashboard-insight-grid'; extra.innerHTML = `<article class="insight-card"><span>حجوزات مرفوضة</span><strong>${summary.rejected_bookings || 0}</strong><small>تحتاج إلى مراجعة أسباب الرفض</small></article><article class="insight-card"><span>إجمالي الرحلات</span><strong>${summary.trips || 0}</strong><small>${summary.open_trips || 0} رحلة مفتوحة الآن</small></article><article class="insight-card"><span>الشركات النشطة</span><strong>${summary.companies || 0}</strong><small>ضمن نطاق الحساب الحالي</small></article>`; host.append(extra); } catch {} };
  const originalOpenAccountDrawer = openAccountDrawer;
  openAccountDrawer = function() { originalOpenAccountDrawer(); const layer = $('.account-drawer-layer'); if (state.user && layer) { const actions = $('.drawer-actions', layer); actions?.insertAdjacentHTML('afterbegin', '<button data-drawer-action="profile"><span>◉</span> تعديل بياناتي</button>'); layer.addEventListener('click', event => { if (event.target.closest('[data-drawer-action="profile"]')) { closeAccountDrawer(); openProfileEditor(); } }); } };
  const enhanceCompanyMediaInputs = () => {
    if (document.body.dataset.companyMediaEnhancements === 'ready') return;
    document.body.dataset.companyMediaEnhancements = 'ready';
    document.addEventListener('change', (event) => {
      const input = event.target;
      if (!(input instanceof HTMLInputElement) || input.type !== 'file' || !/^company_(logo|cover|gallery_\d+|gallery_files)$/.test(input.name)) return;
      const holder = input.closest('.file-picker, .company-gallery-file');
      if (!holder) return;
      if (input.name === 'company_gallery_files') {
        let selection = holder.querySelector('[data-company-gallery-selection]');
        if (!selection) { selection = document.createElement('div'); selection.className = 'company-gallery-selection'; holder.append(selection); }
        selection.innerHTML = '';
        const files = Array.from(input.files || []).slice(0, 6);
        files.forEach((file, index) => { const img = document.createElement('img'); img.alt = `معاينة صورة المعرض ${index + 1}`; img.title = file.name; img.src = URL.createObjectURL(file); selection.append(img); });
        holder.classList.toggle('has-file', files.length > 0);
        const label = holder.querySelector('span'); if (label) label.textContent = files.length ? `تم اختيار ${files.length} صور — اضغط لتغييرها` : 'اختيار صور المعرض';
        return;
      }
      let preview = holder.querySelector('.company-media-preview');
      let selection = holder.querySelector('.company-media-selection');
      if (!preview) { preview = document.createElement('img'); preview.className = 'company-media-preview'; preview.alt = 'معاينة الصورة المختارة'; preview.hidden = true; holder.append(preview); }
      if (!selection) { selection = document.createElement('span'); selection.className = 'company-media-selection'; holder.append(selection); }
      const file = input.files?.[0];
      const oldUrl = preview.dataset.objectUrl;
      if (oldUrl) URL.revokeObjectURL(oldUrl);
      holder.classList.toggle('has-file', Boolean(file));
      if (!file) { preview.hidden = true; preview.removeAttribute('src'); selection.textContent = 'لم يتم اختيار ملف'; return; }
      const objectUrl = URL.createObjectURL(file);
      preview.dataset.objectUrl = objectUrl;
      preview.src = objectUrl;
      preview.hidden = false;
      selection.textContent = file.name;
    });
  };
  enhanceCompanyMediaInputs();
  const clearOperationContextCache = () => { operationContextCache = null; };
  window.BusAdminCore = { $, $$, api, esc, money, dateTime, status, empty, modal, closeModal, showToast, operationContext, clearOperationContextCache, dashTitle, operationsTable, time12Field, timeField, buildSubrouteBody, bindSubrouteTimeSuggestion, separateCreateForm, bindSeparatedCreateForm };
  const startBootstrap = () => bootstrap().catch((error) => {
    console.error('تعذر تهيئة واجهة المنصة:', error);
    if (root) root.innerHTML = `<section class="card login-gate"><h1>تعذر تحميل الواجهة</h1><p class="muted">${esc(error?.message || 'حدث خطأ غير متوقع.')}</p><button class="btn btn-primary" data-action="retry-bootstrap">إعادة المحاولة</button></section>`;
    $('[data-action="retry-bootstrap"]')?.addEventListener('click', bootstrap);
  });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', startBootstrap, { once: true }); else startBootstrap();
